insert into public.store_settings (id, data) values ('main', '{"announcement":{"ar":"توصيل مجاني عند طلب ٣ قطع أو أكثر","he":"משלוח חינם בהזמנת 3 פריטים ומעלה","en":"Free delivery on 3+ items"},"whatsappNumber":"972500000000","instagramUsername":"crowned.demo","freeDeliveryMinItems":3,"timezone":"Asia/Jerusalem","supplierEtaText":{"ar":"التوصيل خلال ١٠–١٤ يومًا تقريبًا من لحظة شحن المورّد","he":"משלוח כ־10–14 ימים ממועד שילוח הספק","en":"Delivery in ~10–14 days from supplier dispatch"},"bankTransferInstructions":{"ar":"تفاصيل الحساب البنكي ستُرسل إليك برسالة تأكيد الطلب. يُشحن الطلب بعد التحقق من الدفع. (نص مبدئي — بانتظار تفاصيل الحساب الفعلية)","he":"פרטי חשבון הבנק יישלחו אליך בהודעת אישור ההזמנה. ההזמנה נשלחת לאחר אימות התשלום. (טקסט זמני — בהמתנה לפרטי החשבון)","en":"Bank account details will be sent in your order confirmation. Your order proceeds after payment verification. (Placeholder — awaiting real account details)"},"internationalMode":"waitlist","internationalNote":{"ar":"الشحن الدولي قريبًا — تواصل معنا عبر واتساب للانضمام لقائمة الانتظار.","he":"משלוח בינלאומי בקרוב — כתבו לנו בוואטסאפ להצטרפות לרשימת ההמתנה.","en":"International delivery coming soon — message us on WhatsApp to join the waiting list."},"paymentMethods":[{"id":"bank_transfer","enabled":true,"testMode":false,"configured":true,"label":{"ar":"تحويل بنكي","he":"העברה בנקאית","en":"Bank transfer"}},{"id":"card","enabled":false,"testMode":true,"configured":false,"label":{"ar":"بطاقة ائتمان","he":"כרטיס אשראי","en":"Credit card"}},{"id":"bit","enabled":false,"testMode":true,"configured":false,"label":{"ar":"Bit","he":"Bit","en":"Bit"}},{"id":"paybox","enabled":false,"testMode":true,"configured":false,"label":{"ar":"PayBox","he":"PayBox","en":"PayBox"}},{"id":"paypal","enabled":false,"testMode":true,"configured":false,"label":{"ar":"PayPal","he":"PayPal","en":"PayPal"}}],"nonAffiliationNote":{"ar":"CROWNED متجر مستقل وغير تابع لأي نادٍ أو اتحاد أو لاعب أو مصنّع. المنتجات نسخ مستوحاة عالية الجودة وليست منتجات رسمية مرخّصة.","he":"CROWNED היא חנות עצמאית שאינה קשורה לאף מועדון, התאחדות, שחקן או יצרן. המוצרים הם רפליקות איכותיות בהשראה — לא מוצרים רשמיים מורשים.","en":"CROWNED is an independent store, not affiliated with any club, federation, player or manufacturer. Products are high-quality inspired replicas — not official licensed merchandise."},"legalEntity":{"name":"","registrationNumber":"","taxNote":""},"policies":{"returns":{"title":{"ar":"سياسة الإلغاء والإرجاع والاستبدال","he":"מדיניות ביטול, החזרה והחלפה","en":"Cancellation, Return & Exchange Policy"},"body":{"ar":"يمكن إلغاء الطلبات فقط قبل بدء الإنتاج. بعد بدء الإنتاج، لا يمكن الإلغاء عادةً.\n\nلأن منتجاتنا تُصنع حسب الطلب، لا نقبل عمومًا الإرجاع أو الاستبدال في الحالات التالية:\n• اختيار مقاس غير صحيح من قبل العميل.\n• تغيير الرأي بعد بدء الإنتاج.\n• المنتجات المخصصة، بما يشمل الاسم أو الرقم أو الشارات أو أي تخصيص آخر.\n\nإذا وصل طلبك تالفًا أو معيبًا أو غير صحيح، يرجى التواصل معنا خلال 48 ساعة من الاستلام مع صور واضحة. سنراجع المشكلة وسنوفر بديلًا أو حلًا مناسبًا آخر عند الاقتضاء.\n\nيرجى استخدام جدول المقاسات قبل الطلب للتأكد من اختيار المقاس الصحيح.","he":"ניתן לבטל הזמנות רק לפני תחילת הייצור. לאחר תחילת הייצור, ביטול אינו אפשרי בדרך כלל.\n\nמכיוון שהמוצרים שלנו מיוצרים לפי הזמנה, אנו בדרך כלל לא מקבלים החזרות או החלפות עבור:\n• מידה שגויה שנבחרה על ידי הלקוח.\n• שינוי דעה לאחר תחילת הייצור.\n• מוצרים בהתאמה אישית, כולל שם, מספר, פאצ''ים או כל התאמה אחרת.\n\nאם ההזמנה הגיעה פגומה, לקויה או שגויה, אנא צרו קשר תוך 48 שעות מהמסירה עם תמונות ברורות. נבחן את הפנייה ובמקרים המתאימים נספק החלפה או פתרון הולם אחר.\n\nאנא השתמשו בטבלת המידות לפני ההזמנה כדי לוודא בחירת מידה נכונה.","en":"Orders may be cancelled only before production has started. Once production has begun, cancellation is generally not possible.\n\nBecause our products are made to order, we generally do not accept returns or exchanges for:\n• Incorrect size selected by the customer.\n• Change of mind after production has started.\n• Customized products, including a name, number, patches, or other personalization.\n\nIf your order arrives damaged, defective, or incorrect, please contact us within 48 hours of delivery with clear photos. We will review the issue and, where appropriate, provide a replacement or another suitable solution.\n\nPlease use the size chart before ordering to ensure you select the correct size."},"needsLegalReview":true},"privacy":{"title":{"ar":"سياسة الخصوصية","he":"מדיניות פרטיות","en":"Privacy Policy"},"body":{"ar":"[نص مبدئي — يتطلب صياغة ومراجعة قانونية قبل الإطلاق]\n\nنجمع بيانات الطلب (الاسم، الهاتف، البريد، العنوان) لمعالجة الطلبات وتحديثات التوصيل. لا نبيع بياناتك. تُخزن البيانات لدى مزوّدي خدمة موثوقين (قاعدة بيانات، مزوّد دفع، مزامنة طلبات). لا تُرسل بيانات شخصية إلى أدوات التحليلات.","he":"[טקסט זמני — נדרש ניסוח ואישור משפטי לפני השקה]\n\nאנו אוספים נתוני הזמנה (שם, טלפון, אימייל, כתובת) לצורך טיפול בהזמנות ועדכוני משלוח. איננו מוכרים את הנתונים שלך. הנתונים נשמרים אצל ספקי שירות אמינים (מסד נתונים, ספק תשלום, סנכרון הזמנות). מידע אישי אינו נשלח לכלי אנליטיקה.","en":"[Placeholder — requires drafting and legal review before launch]\n\nWe collect order data (name, phone, email, address) to process orders and delivery updates. We do not sell your data. Data is stored with trusted processors (database, payment provider, order sync). Personal information is never sent to analytics tools."},"needsLegalReview":true},"terms":{"title":{"ar":"الشروط والأحكام","he":"תנאי שימוש","en":"Terms & Conditions"},"body":{"ar":"[نص مبدئي — يتطلب صياغة ومراجعة قانونية قبل الإطلاق]\n\nباستخدامك للموقع وإتمام الطلب فأنت توافق على سياسات المتجر، بما فيها سياسة الإلغاء والإرجاع وسياسة الخصوصية. الأسعار بالشيكل وتشمل ما يُذكر صراحةً فقط.","he":"[טקסט זמני — נדרש ניסוח ואישור משפטי לפני השקה]\n\nהשימוש באתר וביצוע הזמנה מהווים הסכמה למדיניות החנות, כולל מדיניות הביטול וההחזרה ומדיניות הפרטיות. המחירים בשקלים וכוללים רק את המפורט במפורש.","en":"[Placeholder — requires drafting and legal review before launch]\n\nUsing this site and placing an order constitutes agreement to the store policies, including the cancellation/return policy and privacy policy. Prices are in ILS and include only what is explicitly stated."},"needsLegalReview":true},"accessibility":{"title":{"ar":"بيان إتاحة الوصول","he":"הצהרת נגישות","en":"Accessibility Statement"},"body":{"ar":"صُمم هذا المتجر وفق معايير WCAG 2.2 مستوى AA: تنقّل كامل بلوحة المفاتيح، تباين ألوان مناسب، دعم قارئات الشاشة، ودعم تقليل الحركة. نعمل باستمرار على تحسين الإتاحة — إذا واجهت صعوبة، راسلنا عبر صفحة التواصل وسنساعدك بسرعة.","he":"החנות תוכננה בהתאם להנחיות WCAG 2.2 רמה AA: ניווט מלא במקלדת, ניגודיות צבעים מתאימה, תמיכה בקוראי מסך ותמיכה בהפחתת אנימציה. אנו פועלים לשיפור מתמיד של הנגישות — אם נתקלת בקושי, פנו אלינו דרך עמוד יצירת הקשר ונסייע במהירות.","en":"This store is built to WCAG 2.2 level AA guidelines: full keyboard navigation, appropriate color contrast, screen-reader support and reduced-motion support. We continuously improve accessibility — if you encounter difficulty, contact us via the contact page and we will help promptly."},"needsLegalReview":false}}}'::jsonb);
